def __repr__(self) -> str:
    return f"<{self.status} {self.url}>"

def to_dict(self) -> dict[str, Any]:
    """Serialize this response to a dict.

    The dict can be used to restore the response with :func:`~scrapy.utils.response.response_from_dict`.
    """
    d: dict[str, Any] = {
        "url": self.url,
        "status": self.status,
        "headers": self.headers.to_dict(),
        "body": self.body,
    }
    if self.flags:
        d["flags"] = self.flags
    if self.certificate is not None:
        d["certificate"] = self.certificate
    if self.ip_address is not None:
        d["ip_address"] = str(self.ip_address)
    if self.protocol is not None:
        d["protocol"] = self.protocol
    if self.request is not None:
        d["request"] = self.request.to_dict()
    if self.__class__ is not Response:
        d["_class"] = self.__class__.__module__ + "." + self.__class__.__name__
    return d
